from collections import Counter
import json, os

def transform(g):
    """Background cells that break the grid's repeating pattern (stripe rows / vertical period) become 1."""
    h, w = len(g), len(g[0])
    b = Counter(v for r in g for v in r).most_common(1)[0][0]
    out = [r[:] for r in g]
    changed = True
    while changed:
        changed = False
        # stripe rows: rows that are one nonzero color except for bg gaps -> fill gaps with 1
        for i in range(h):
            vals = {v for v in g[i] if v != b}
            if len(vals) == 1 and g[i].count(b) < w and g[i].count(list(vals)[0]) >= w - g[i].count(b):
                nz = list(vals)[0]
                for j in range(w):
                    if out[i][j] == b:
                        out[i][j] = 1; changed = True
        # vertical periodicity: bg cell where the period-p counterpart is nonzero -> 1
        best = None
        for p in range(1, h):
            tot = sum(1 for i in range(h-p) for j in range(w) if g[i][j] != g[i+p][j])
            if tot and (best is None or tot < best[0]):
                best = (tot, p)
        if best and best[0] <= h*w//4:
            tot, p = best
            for i in range(h-p):
                for j in range(w):
                    a, c = g[i][j], g[i+p][j]
                    if a != c:
                        if a == b and c != b: out[i][j] = 1; changed = True
                        elif c == b and a != b: out[i+p][j] = 1; changed = True
        g = out
    return out

