def mark_pattern_deviations(grid, mark=1):
    """Rows form motif blocks (contiguous runs of non-background rows). Between two
    blocks, cells that break the row-wise repetition and match the background/solid
    color are marked with `mark` (pattern-error marker)."""
    solid = background(grid)
    idx = [i for i, row in enumerate(grid) if any(v != solid for v in row)]
    blocks = []
    for i in idx:
        if blocks and i == blocks[-1][-1] + 1:
            blocks[-1].append(i)
        else:
            blocks.append([i])
    out = [row[:] for row in grid]
    for bi in range(len(blocks)):
        for bj in range(bi + 1, len(blocks)):
            for r1, r2 in zip(blocks[bi], blocks[bj]):
                a, b = grid[r1], grid[r2]
                sm = SequenceMatcher(None, a, b)
                am, bm = set(), set()
                for i, j, n in sm.get_matching_blocks():
                    for k in range(n):
                        am.add(i + k); bm.add(j + k)
                sa = [i for i in range(len(a)) if i not in am and a[i] == solid]
                sb = [j for j in range(len(b)) if j not in bm and b[j] == solid]
                if sa and not sb:
                    for i in sa: out[r1][i] = mark
                elif sb and not sa:
                    for j in sb: out[r2][j] = mark
    return out

